const AvbDescriptor * * avb_descriptor_get_all ( const uint8_t * image_data , size_t image_size , size_t * out_num_descriptors ) { size_t num_descriptors = 0 ; SetDescriptorData data ; avb_descriptor_foreach ( image_data , image_size , count_descriptors , & num_descriptors ) ; data . descriptor_number = 0 ; data . descriptors = avb_calloc ( sizeof ( const AvbDescriptor * ) * ( num_descriptors + 1 ) ) ; if ( data . descriptors == NULL ) { return NULL ; } avb_descriptor_foreach ( image_data , image_size , set_descriptors , & data ) ; avb_assert ( data . descriptor_number == num_descriptors ) ; return data . descriptors ; } 